#!/usr/bin/env python3
"""Source-separated 24-case diagnostic. No training and no on-disk dcurr edits.
Copy this file beside dcurr/, scope_gate_v07.py and runs/.
prepare --accept-ai-reviewed-candidates; evaluate; compare.
All guide changes are process-local, with exact message hashes recorded.
"""
from __future__ import annotations
import argparse, ast, copy, hashlib, html, importlib, importlib.util, inspect
import json, os, runpy, subprocess, sys, time
from collections import Counter, defaultdict
from datetime import datetime, timezone
from pathlib import Path
VERSION='new-source-reason-v1.0.0'
DEFAULT_DIR='data/new_source_reason_v10'
ADAPTER='runs/evidence_training_v05_position_e2'
E2_SHA='c16813cc75b33133fbdc4065e991ff0bea9580a75440900eae0fc2be2e4d44c5'
MODEL='Qwen/Qwen3.5-2B'
REVISION='15852e8c16360a2fea060d615a32b45270f8a8fc'
ARMS=('baseline','guide')


def now(): return datetime.now(timezone.utc).isoformat()
def require(ok, message):
    if not ok: raise ValueError(message)
def strict(text):
    def pairs(items):
        out={}
        for k,v in items:
            require(k not in out, 'Duplicate JSON key: '+k); out[k]=v
        return out
    def bad(x): raise ValueError('Non-finite JSON: '+x)
    return json.loads(text,object_pairs_hook=pairs,parse_constant=bad)
def canon(x): return json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False)
def objsha(x): return hashlib.sha256(canon(x).encode()).hexdigest()
def sha(p):
    h=hashlib.sha256()
    with Path(p).open('rb') as f:
        for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
    return h.hexdigest()
def readj(p): return strict(Path(p).read_text(encoding='utf-8-sig'))
def readl(p):
    rows=[strict(x) for x in Path(p).read_text(encoding='utf-8-sig').splitlines() if x.strip()]
    require(all(isinstance(x,dict) for x in rows),'JSONL rows must be objects');return rows
def writej(p,x):
    with Path(p).open('x',encoding='utf-8') as f:f.write(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def writel(p,rs):
    with Path(p).open('x',encoding='utf-8') as f:
        for r in rs:f.write(json.dumps(r,ensure_ascii=False,allow_nan=False)+'\n')
def local(root,name):
    p=Path(name); require(not p.is_absolute() and '..' not in p.parts,'Relative project path required')
    p=root/p;require(p.resolve().is_relative_to(root.resolve()),'Path escapes project');return p

def index(rows):
    out={}
    for r in rows:
        k=r.get('case_id');require(isinstance(k,str) and k not in out,'Missing/duplicate case ID');out[k]=r
    return out

def envelope(c): return {k:copy.deepcopy(c[k]) for k in ('role','packet')}

def load_gate(root):
    p=root/'scope_gate_v07.py';require(p.is_file(),'Missing scope_gate_v07.py beside dcurr/')
    sp=importlib.util.spec_from_file_location('_ns10_scope_gate',p); m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)
    require(callable(getattr(m,'gate_input',None)),'Unsupported scope gate interface');return m

def modules(root):
    require((root/'dcurr/common.py').is_file(),'Run beside the existing dcurr/ directory')
    sys.path.insert(0,str(root))
    c=importlib.import_module('dcurr.common');p=importlib.import_module('dcurr.prompts')
    require(Path(c.__file__).resolve()==(root/'dcurr/common.py').resolve(),'Wrong dcurr imported')
    require(callable(getattr(p,'build_messages',None)),'Current prompts.build_messages API missing')
    # Check the exact hook BEFORE starting a GPU subprocess.
    tree=ast.parse((root/'dcurr/evaluate.py').read_text(encoding='utf-8'))
    imported=any(isinstance(n,ast.ImportFrom) and (n.module or '').endswith('prompts') and any(a.name=='build_messages' for a in n.names) for n in ast.walk(tree))
    require(imported,'Evaluator does not import prompts.build_messages; stop before GPU and inspect its API')
    return c,p

def guided(messages, guide):
    ms=copy.deepcopy(messages)
    require(isinstance(ms,list) and len(ms)==2 and [x.get('role') for x in ms]==['system','user'],'Expected exactly system+user input; no gold/assistant allowed')
    require(all(isinstance(x.get('content'),str) for x in ms),'Text messages required')
    if guide:ms[0]['content']+='\n\n'+guide
    return ms

def source_overlap(root):
    # Restrict to pre-existing training/export metadata. Do not search new evaluation labels.
    required=['data/train_curriculum_physics20_v02_r1.jsonl','data/evidence_training_v05/position210.jsonl']
    optional=['data/train_curriculum_physics20_v02_r1.manifest.json','data/evidence_training_v05/position210.manifest.json','data/evidence_training_v05/manifest.json']
    frozen={}; hits=[]; groups=set(); sids=set()
    for name in required+optional:
        path=local(root,name)
        if not path.is_file():
            require(name not in required,'Training export missing for overlap audit: '+name);continue
        frozen[name]=sha(path);text=path.read_text(encoding='utf-8')
        if path.suffix=='.jsonl':
            for r in readl(path):
                meta=r.get('metadata',{});groups.update(meta.get('program_groups',[]));sids.update(meta.get('source_ids',[]))
        for s in PAYLOAD['registry']:
            for term in s['novelty_terms']:
                if term.casefold() in text.casefold():hits.append({'path':name,'source_id':s['source_id'],'term':term})
    require(not hits,'Possible prior-use overlap in training exports: '+json.dumps(hits,ensure_ascii=False))
    # Registry membership alone is NOT a claim of training use; report separately.
    registered=[]
    for p in sorted((root/'sources').glob('*manifest*.json')):
        frozen[str(p.relative_to(root))]=sha(p);txt=p.read_text(encoding='utf-8')
        for s in PAYLOAD['registry']:
            if any(t.casefold() in txt.casefold() for t in s['novelty_terms']):registered.append({'path':str(p.relative_to(root)),'source_id':s['source_id']})
    report={'status':'NO_IDENTITY_MATCH_IN_SCANNED_TRAINING_ARTIFACTS','scanned_files':frozen,'observed_training_groups':sorted(groups),'observed_training_source_ids':sorted(sids),'already_registered_sources':registered,'limits':'Artifact identity screening only. Alias/semantic overlap, all prior conversations, and base pretraining exposure cannot be exhausted here. Shared methods/references are expected. Not an independent final holdout.'}
    return report,frozen

def validate_payload():
    rows=PAYLOAD['cases'];require(len(rows)==24 and len(index(rows))==24,'Need 24 scenarios')
    require(len(PAYLOAD['registry'])==3,'Need 3 source groups')
    groups=defaultdict(list)
    for r in rows:
        groups[r['pair_id']].append(r)
        a=r['expected'];p=r['packet'];require(a['claim_id']==p['claim_id'],'Claim mismatch')
        require(r['authoring']['human_review_performed'] is False and r['authoring']['real_measurement_available'] is False,'Authorship mismatch')
        require(a['action'] in ('CHALLENGE','REQUEST_EVIDENCE','NO_ACTION_REQUIRED'),'Bad action')
        require(a['action']!='REQUEST_EVIDENCE' or a.get('requested_evidence'),'Request IDs missing')
    require(Counter(r['expected']['action'] for r in rows)=={'NO_ACTION_REQUIRED':12,'CHALLENGE':6,'REQUEST_EVIDENCE':6},'Wrong distribution')
    require(len(groups)==12,'Need 12 related pairs')
    for pair,rr in groups.items():
        require(len(rr)==2 and rr[0]['packet']['review_question']==rr[1]['packet']['review_question'],'Pair question changed')
        require(rr[0]['packet']['case_packet']['proposal']==rr[1]['packet']['case_packet']['proposal'],'Pair proposal changed')
        require(rr[0]['expected']['action']!=rr[1]['expected']['action'],'Pair does not flip action')
    require(hashlib.sha256(PAYLOAD['guide'].encode()).hexdigest()==PAYLOAD['guide_sha256'],'Guide changed')


def review_text():
    out=['# 새 출처 24개 평가 후보 — AI 작성·AI 논리 검토','',
    '사람 전문가 승인이나 실제 시험 결과가 아니다. 원문 근거는 웹의 PDF 텍스트로 확인했다. PDF 스크린샷 요청이 실패하여 그림·표를 재해석하지 않았고 로컬 원본 PDF 해시는 없다.',
    '모든 OBS와 식별자·83/191 Hz 같은 사례 수치는 새 가상 조건이다. 문헌 원리는 출처별 정의를 그대로 유지한다. e2 가중치/출력은 새 평가에 대해 아직 실행되지 않았다.',
    'v09 분류 설명은 24개 작성 이전 파일과 바이트가 같다. 12쌍은 관련 사례이고 독립 표본 24개로 추론하지 않는다. 3개 다른 프로그램은 기존 4개 출처 기준이며 로컬 prior-use audit을 함께 확인한다.','']
    for s in PAYLOAD['registry']:
        out+=['## '+s['title'],s['scope_note_ko'],f"출처: {s['landing_url']}",f"원문: {s['pdf_url']}",'']
    for t in PAYLOAD['topics']:
        out+=['## '+t['topic_id'],t['review_ko'],'']
        for r in sorted([r for r in PAYLOAD['cases'] if r['pair_id']=='NS10-'+t['topic_id']],key=lambda r:r['case_id']):
            rec=next(x for x in r['packet']['case_packet']['evidence'] if x['evidence_id'] in r['expected']['evidence_refs'])
            out+=[f"### {r['case_id']}",'질문: '+t['question'],'제안: '+t['proposal'],'가상 현재 관측: '+rec['text'],'AI 정답 후보: `'+canon(r['expected'])+'`','']
    return '\n\n'.join(out)

def prepare(root,outdir,accept):
    require(accept,'This is AI-authored diagnostic data. Add --accept-ai-reviewed-candidates to opt in; this is not human/source/training approval.')
    validate_payload();dest=local(root,outdir)
    require(not dest.exists(),'Output directory exists; preserve it or use a new --outdir')
    common,prompts=modules(root);gate=load_gate(root)
    weight=local(root,ADAPTER)/'adapter_model.safetensors'
    require(weight.is_file() and sha(weight)==E2_SHA,'Expected measured position-e2 adapter missing/changed')
    overlap,frozen=source_overlap(root)
    prior_guide=root/'DoriLab_v09_Next_Step/reason_guide_inference_candidate.txt'
    if prior_guide.is_file():
        require(sha(prior_guide)==PAYLOAD['guide_sha256'],'Local v09 guide differs; keep the predeclared guide unchanged')
        frozen[str(prior_guide.relative_to(root))]=sha(prior_guide)
    rows=[];messages={a:[] for a in ARMS};checks=[];events=[]
    for c in PAYLOAD['cases']:
        env,event=gate.gate_input(envelope(c)) # no expected/authoring passed to gate
        cc=copy.deepcopy(c);cc['packet']=env['packet']
        for a in cc['acceptable_answers']:common.validate_answer(a,env)
        base=guided(prompts.build_messages(cc['role'],cc['packet']),'')
        # Also ensure the provided builder supports supervised construction consistently.
        complete=prompts.build_messages(cc['role'],cc['packet'],cc['expected'])
        require(complete[:-1]==base and complete[-1]['role']=='assistant','Train/inference prompt builder mismatch')
        for arm in ARMS:
            ms=guided(base,PAYLOAD['guide'] if arm=='guide' else '')
            messages[arm].append({'case_id':cc['case_id'],'role_packet_sha256':objsha(env),'messages':ms,'messages_sha256':objsha(ms)})
        checks.append({'case_id':cc['case_id'],'gate_used_gold':False,'kept':event.get('included',[]),'excluded':event.get('excluded_from_model_context',[])})
        events.append({'case_id':cc['case_id'],**event});rows.append(cc)
    # Preserve current implementation identity and actual generated model messages.
    for path in sorted((root/'dcurr').glob('*.py')):frozen[str(path.relative_to(root))]=sha(path)
    for name in ('scope_gate_v07.py','data/action_schema_v02.json',ADAPTER+'/adapter_config.json'):
        p=local(root,name);require(p.is_file(),'Missing '+name);frozen[name]=sha(p)
    dest.mkdir(parents=True)
    writel(dest/'raw_cases24_candidate.jsonl',PAYLOAD['cases']);writel(dest/'evaluation_cases24.jsonl',rows)
    writel(dest/'gate_events.jsonl',events);writej(dest/'source_registry.json',PAYLOAD['registry']);writej(dest/'source_facts.json',PAYLOAD['facts'])
    writej(dest/'source_overlap_audit.json',overlap)
    (dest/'AI_REVIEW_KO.md').write_text(review_text(),encoding='utf-8')
    (dest/'REVIEW.html').write_text('<!doctype html><html lang="ko"><meta charset="utf-8"><title>v10 AI 검토</title><style>body{max-width:1100px;margin:2rem auto;font:16px/1.7 sans-serif}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>새 출처 평가 후보 · AI 검토</h1><pre>'+html.escape(review_text())+'</pre></html>',encoding='utf-8')
    (dest/'reason_guide_v09_unchanged.txt').write_text(PAYLOAD['guide'],encoding='utf-8')
    for arm in ARMS:
        writel(dest/f'inputs_{arm}24.jsonl',messages[arm])
        # Used for tokenizer/mask preflight ONLY; never provided to inference.
        sft=[]
        for c,inp in zip(rows,messages[arm]):
            sft.append({'id':c['case_id'],'messages':inp['messages']+[{'role':'assistant','content':json.dumps(c['expected'],ensure_ascii=False)}],'metadata':{'purpose':'EVALUATION_PREFLIGHT_ONLY_NOT_TRAINING','training_release_approved':False}})
        writel(dest/f'preflight_only_{arm}24.jsonl',sft)
    generated={p.name:sha(p) for p in dest.iterdir() if p.is_file()}
    m={'version':VERSION,'created_at_utc':now(),'script_sha256':sha(Path(__file__)),'payload_sha256':objsha(PAYLOAD),'model':MODEL,'revision':REVISION,'adapter':ADAPTER,'adapter_sha256':E2_SHA,'max_length':2048,'max_new_tokens':384,'seed':42,'arms':list(ARMS),'arm_order':list(ARMS),'guide_sha256':PAYLOAD['guide_sha256'],'frozen_files':frozen,'generated_files':generated,'candidate_use_authorized':True,'author_type':'AI','human_review_performed':False,'training_executed':False,'inference_executed':False,'cases':24,'related_pairs':12,'source_groups':3,'purpose':'SOURCE_SEPARATED_SMALL_DEVELOPMENT_DIAGNOSTIC_NOT_FINAL_HOLDOUT','interpretation':'Same model and gate; system guidance is added in one arm. Input token lengths and loading/warmup times are not matched. No single-run causal/statistical generalization claim.'}
    writej(dest/'manifest.json',m)
    print('NEW SOURCE PREPARE: PASS\n24 AI-reviewed candidates / 12 pairs / 3 source groups; no training or model load.\nNext: evaluate, then compare.')

def plan(root,outdir):
    d=local(root,outdir);m=readj(d/'manifest.json')
    require(m['version']==VERSION and m['script_sha256']==sha(Path(__file__)) and m['payload_sha256']==objsha(PAYLOAD),'Script/payload changed after prepare')
    for name,h in m['frozen_files'].items():require(sha(local(root,name))==h,'Frozen project file changed: '+name)
    for name,h in m['generated_files'].items():require(sha(local(d,name))==h,'Prepared file changed: '+name)
    require(sha(local(root,m['adapter'])/'adapter_model.safetensors')==m['adapter_sha256'],'Adapter changed')
    return d,m

def install_hook(prompts,arm,inputs,trace_path):
    original=prompts.build_messages
    targets={x['role_packet_sha256']:x for x in inputs}
    require(len(targets)==24,'Duplicate inference envelopes')
    trace=[]
    def wrapped(*args,**kwargs):
        bound=inspect.signature(original).bind(*args,**kwargs); bound.apply_defaults()
        # Do not accept a supervised answer at the inference hook.
        require(all(v is None for k,v in list(bound.arguments.items())[2:]),'Gold/extra argument reached inference prompt builder')
        vals=list(bound.arguments.values());require(len(vals)>=2,'Unexpected builder signature')
        role,packet=vals[0],vals[1];env={'role':role,'packet':packet};key=objsha(env)
        require(key in targets,'Unexpected or gold-contaminated model input')
        ms=guided(original(*args,**kwargs),PAYLOAD['guide'] if arm=='guide' else '')
        target=targets[key];require(objsha(ms)==target['messages_sha256'] and ms==target['messages'],'Actual prompt differs from predeclared arm input')
        require(target['case_id'] not in [t['case_id'] for t in trace],'Prompt generated twice for one case')
        item={'case_id':target['case_id'],'messages_sha256':objsha(ms),'arm':arm};trace.append(item)
        with Path(trace_path).open('a',encoding='utf-8') as f:f.write(json.dumps(item)+'\n')
        return ms
    prompts.build_messages=wrapped
    return original,trace

def worker(root,outdir,arm):
    d,m=plan(root,outdir);_,prompts=modules(root); os.chdir(root)
    from transformers import set_seed
    set_seed(m['seed'])
    inputs=readl(d/f'inputs_{arm}24.jsonl');trace_path=d/'results'/f'{arm}.prompt_trace.jsonl'
    require(not trace_path.exists(),'Existing prompt trace; preserve incomplete run')
    original,trace=install_hook(prompts,arm,inputs,trace_path)
    result=d/'results'/f'{arm}.jsonl'
    sys.argv=['dcurr.evaluate','--cases',str(d/'evaluation_cases24.jsonl'),'--adapter',m['adapter'],'--out',str(result),'--model',m['model'],'--revision',m['revision'],'--max-new-tokens',str(m['max_new_tokens']),'--purpose','CANDIDATE_DIAGNOSTIC']
    try:runpy.run_module('dcurr.evaluate',run_name='__main__')
    finally:prompts.build_messages=original
    require(len(trace)==24,'Evaluator did not invoke checked prompt builder for all 24 cases')
    rr=readl(result);require(set(index(rr))==set(index(readl(d/'evaluation_cases24.jsonl'))),'Incomplete evaluator output')
    writej(d/'results'/f'{arm}.execution.json',{'arm':arm,'completed_at_utc':now(),'inference_executed':True,'training_executed':False,'adapter_sha256':m['adapter_sha256'],'guide_sha256':m['guide_sha256'] if arm=='guide' else None,'effective_prompt_trace_sha256':sha(trace_path),'result_sha256':sha(result),'summary_sha256':sha(result.with_suffix('.summary.json')),'prompt_file_sha256':sha(root/'dcurr/prompts.py'),'warning':'dcurr summary prompt-file hash identifies the unchanged source file, NOT effective guided messages; use the checked trace for effective prompts.'})

def logged(root,cmd,path):
    require(not path.exists(),'Existing log '+str(path));start=time.perf_counter()
    print('\nRUN:',' '.join(map(str,cmd)),flush=True)
    with path.open('x',encoding='utf-8') as log:
        log.write('COMMAND '+json.dumps(cmd)+'\n');log.flush()
        with subprocess.Popen(cmd,cwd=root,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace') as p:
            for line in p.stdout:print(line,end='',flush=True);log.write(line);log.flush()
            rc=p.wait()
    require(rc==0,'Subprocess failed; preserved '+str(path))
    return time.perf_counter()-start

def evaluate(root,outdir):
    d,m=plan(root,outdir);(d/'results').mkdir(exist_ok=True);(d/'logs').mkdir(exist_ok=True)
    # Tokenizer-only preflight of BOTH arms before any GPU model load.
    pf=d/'preflight_complete.json'
    if not pf.exists():
        for arm in ARMS:
            stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%f')
            logged(root,[sys.executable,'-m','dcurr.preflight','--data',str(d/f'preflight_only_{arm}24.jsonl'),'--max-length',str(m['max_length']),'--model',m['model'],'--revision',m['revision']],d/'logs'/f'preflight_{arm}_{stamp}.log')
        writej(pf,{'at_utc':now(),'manifest_sha256':sha(d/'manifest.json')})
    else:require(readj(pf)['manifest_sha256']==sha(d/'manifest.json'),'Preflight manifest mismatch')
    for arm in ARMS:
        done=d/'results'/f'{arm}.execution.json';result=d/'results'/f'{arm}.jsonl';started=d/'results'/f'{arm}.started.json'
        if done.exists():
            record=readj(done);require(sha(result)==record['result_sha256'] and sha(result.with_suffix('.summary.json'))==record['summary_sha256'] and sha(d/'results'/f'{arm}.prompt_trace.jsonl')==record['effective_prompt_trace_sha256'],'Completed output/summary/trace changed');print('SKIP VERIFIED COMPLETE',arm);continue
        require(not started.exists() and not result.exists(),'Incomplete prior run; preserve it and prepare a NEW --outdir')
        writej(started,{'at_utc':now(),'manifest_sha256':sha(d/'manifest.json'),'arm':arm})
        wall=logged(root,[sys.executable,str(Path(__file__).resolve()),'_worker','--root',str(root),'--outdir',outdir,'--arm',arm],d/'logs'/f'inference_{arm}.log')
        require(done.exists(),'Worker did not write verified completion')
        writej(d/'results'/f'{arm}.walltime.json',{'subprocess_seconds':wall,'includes':'process setup, model load, generation and evaluation; arm order is fixed baseline then guide'})
    print('BOTH EVALUATIONS COMPLETE. Next: compare')


def score(common,c,row):
    err=None;obj=None;valid=False;parsed_ok=False
    try:
        obj=strict(row['raw_output']);require(isinstance(obj,dict),'Output must be one object');parsed_ok=True
        refs=obj.get('evidence_refs');require(isinstance(refs,list) and all(isinstance(x,str) for x in refs) and len(refs)==len(set(refs)),'Bad/duplicate refs')
        require(not row.get('hit_generation_limit',False),'Generation limit reached')
        common.validate_answer(obj,envelope(c));valid=True
    except Exception as ex:err={'type':type(ex).__name__,'message':getattr(ex,'message',str(ex))}
    exp=c['expected'];action=bool(isinstance(obj,dict) and obj.get('action')==exp['action'])
    refok=bool(isinstance(obj,dict) and isinstance(obj.get('evidence_refs'),list) and all(isinstance(x,str) for x in obj['evidence_refs']) and len(set(obj['evidence_refs']))==len(obj['evidence_refs']) and set(obj['evidence_refs'])==set(exp['evidence_refs']))
    reason_app='reason' in exp
    reason_ok=bool(reason_app and action and isinstance(obj,dict) and obj.get('reason')==exp['reason'])
    matched=bool(valid and common.answer_matches(exp,obj))
    return {'action_correct':action,'schema_and_refs_valid':valid,'strict_json_object':parsed_ok,'reference_exact':refok,'reason_applicable':reason_app,'reason_correct_when_action_correct':reason_ok,'strict_contract_pass':matched and refok,'wrongly_accepts_refuted_proposal':exp['action']=='CHALLENGE' and isinstance(obj,dict) and obj.get('action')=='NO_ACTION_REQUIRED','unnecessary_intervention':exp['action']=='NO_ACTION_REQUIRED' and isinstance(obj,dict) and obj.get('action') in ('CHALLENGE','REQUEST_EVIDENCE'),'stored_contract_pass':row.get('contract_pass'),'duplicate_or_invalid_json':not parsed_ok,'expected':exp,'parsed':obj,'validation_error':err,'raw_output':row.get('raw_output'),'prompt_tokens':row.get('prompt_tokens'),'generated_tokens':row.get('generated_tokens'),'generation_seconds':row.get('generation_seconds')}

def summarise(rows):
    keys=['action_correct','schema_and_refs_valid','reference_exact','strict_contract_pass','wrongly_accepts_refuted_proposal','unnecessary_intervention']
    d={'cases':len(rows),**{k:sum(bool(r[k]) for r in rows) for k in keys}}
    d['reason_given_correct_action']={'correct':sum(r['reason_correct_when_action_correct'] for r in rows),'eligible':sum(r['reason_applicable'] and r['action_correct'] for r in rows)}
    d['reason_joint_correct']={'correct':sum(r['reason_correct_when_action_correct'] for r in rows),'reason_cases':sum(r['reason_applicable'] for r in rows)}
    for k in ('prompt_tokens','generated_tokens','generation_seconds'):d[k+'_total']=sum(r[k] for r in rows if isinstance(r.get(k),(int,float)))
    return d

def compare(root,outdir):
    d,m=plan(root,outdir);common,_=modules(root);cases=readl(d/'evaluation_cases24.jsonl');cm=index(cases);allrows=[];arms={};byarm={}
    for arm in ARMS:
        dr=d/'results';result=dr/f'{arm}.jsonl';ex=readj(dr/f'{arm}.execution.json');trace=readl(dr/f'{arm}.prompt_trace.jsonl')
        require(ex['arm']==arm and ex['inference_executed'] is True and ex['adapter_sha256']==m['adapter_sha256'],'Wrong execution identity')
        require(ex['guide_sha256']==(m['guide_sha256'] if arm=='guide' else None),'Wrong arm policy')
        require(sha(result)==ex['result_sha256'] and sha(result.with_suffix('.summary.json'))==ex['summary_sha256'] and sha(dr/f'{arm}.prompt_trace.jsonl')==ex['effective_prompt_trace_sha256'],'Run files changed')
        declared={r['case_id']:r['messages_sha256'] for r in readl(d/f'inputs_{arm}24.jsonl')}
        require({r['case_id']:r['messages_sha256'] for r in trace}==declared and len(trace)==24,'Effective prompt trace mismatch')
        sm=readj(result.with_suffix('.summary.json'))
        for k,v in {'records':24,'model':m['model'],'adapter_sha256':m['adapter_sha256'],'case_file_sha256':sha(d/'evaluation_cases24.jsonl')}.items():require(sm.get(k)==v,'Evaluator identity mismatch: '+k)
        rr=index(readl(result));require(set(rr)==set(cm),'Incomplete case IDs')
        sc={cid:score(common,c,rr[cid]) for cid,c in cm.items()};byarm[arm]=sc
        ar={'overall':summarise(list(sc.values())),'by_source':{},'by_action':{},'guide_focus':{},'pair_both_pass':0}
        for sid in sorted({c['source_id'] for c in cases}):ar['by_source'][sid]=summarise([sc[c['case_id']] for c in cases if c['source_id']==sid])
        for action in ('CHALLENGE','REQUEST_EVIDENCE','NO_ACTION_REQUIRED'):ar['by_action'][action]=summarise([sc[c['case_id']] for c in cases if c['expected']['action']==action])
        for focus in (True,False):ar['guide_focus']['targeted_topics' if focus else 'other_topics']=summarise([sc[c['case_id']] for c in cases if c['authoring']['guide_focus']==focus])
        groups=defaultdict(list)
        for c in cases:groups[c['pair_id']].append(sc[c['case_id']]['strict_contract_pass'])
        ar['pair_both_pass']=sum(all(g) for g in groups.values());ar['pairs']=len(groups);arms[arm]=ar
    for c in cases:
        b,g=byarm['baseline'][c['case_id']],byarm['guide'][c['case_id']]
        allrows.append({'case_id':c['case_id'],'pair_id':c['pair_id'],'source_id':c['source_id'],'domain':c['domain'],'baseline':b,'guide':g,'action_changed':b['parsed'] is not None and g['parsed'] is not None and b['parsed'].get('action')!=g['parsed'].get('action'),'strict_gain':not b['strict_contract_pass'] and g['strict_contract_pass'],'strict_loss':b['strict_contract_pass'] and not g['strict_contract_pass']})
    res={'version':VERSION,'at_utc':now(),'inference_executed':True,'training_executed':False,'unique_scenarios':24,'related_pairs':12,'program_groups':3,'adapter_sha256':m['adapter_sha256'],'arms':arms,'paired_gain':sum(x['strict_gain'] for x in allrows),'paired_loss':sum(x['strict_loss'] for x in allrows),'action_changed':sum(x['action_changed'] for x in allrows),'guide_sha256':m['guide_sha256'],'limits':m['interpretation'],'label_provenance':'AI-authored and AI-reviewed before outputs, not independent human truth; public source principles + synthetic records; do not auto-train on this evaluation.'}
    require(not (d/'comparison.json').exists(),'Comparison exists; preserve before re-analysis')
    writej(d/'comparison.json',res);writel(d/'comparison_cases.jsonl',allrows)
    lines=['# 새 출처 reason 설명 비교','', 'AI 라벨 · 3개 프로그램 · 12쌍/24개 관련 시나리오 · 독립 최종 성능평가 아님','', '|항목|기본 e2|e2 + v09 설명|','|---|---:|---:|']
    for key,label in [('action_correct','Action 정답'),('reference_exact','근거 정확 선택'),('strict_contract_pass','전체 계약 통과'),('wrongly_accepts_refuted_proposal','잘못된 제안 수용'),('unnecessary_intervention','불필요한 개입')]:lines.append(f"|{label}|{arms['baseline']['overall'][key]}|{arms['guide']['overall'][key]}|")
    lines+=['',f"전체 계약 새 통과 {res['paired_gain']}건 / 퇴행 {res['paired_loss']}건. reason 조건부 지표는 comparison.json에 분모와 함께 저장.",'', '설명 추가는 입력 토큰 길이도 바꾼다. 한 번의 작은 평가로 최적 정책/통계적 일반화를 확정하지 않는다. 실제 engineering approval 및 training release는 발생하지 않는다.','', '## 사례별 결과']
    for r in allrows:
        if r['strict_gain'] or r['strict_loss'] or not r['guide']['strict_contract_pass']:
            lines += [f"### {r['case_id']}", '기준: `'+canon(r['guide']['expected'])+'`','기본: `'+canon(r['baseline']['parsed'])+'`','설명: `'+canon(r['guide']['parsed'])+'`','']
    (d/'RESULTS_KO.md').write_text('\n'.join(lines),encoding='utf-8')
    print(json.dumps(res,ensure_ascii=False,indent=2));print('SAVED:',d/'comparison.json',d/'comparison_cases.jsonl')

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('command',choices=['prepare','evaluate','compare','_worker']);p.add_argument('--root',type=Path,default=Path.cwd());p.add_argument('--outdir',default=DEFAULT_DIR);p.add_argument('--accept-ai-reviewed-candidates',action='store_true');p.add_argument('--arm',choices=ARMS);a=p.parse_args();root=a.root.resolve()
    try:
        if a.command=='prepare':prepare(root,a.outdir,a.accept_ai_reviewed_candidates)
        elif a.command=='evaluate':evaluate(root,a.outdir)
        elif a.command=='compare':compare(root,a.outdir)
        else:require(a.arm,'--arm required');worker(root,a.outdir,a.arm)
    except (ValueError,KeyError,FileNotFoundError,ImportError) as e:
        print('STOP:',e,file=sys.stderr);print('Existing files were not overwritten. Preserve outputs/logs before retrying.',file=sys.stderr);raise SystemExit(1)

